import React, {memo, useMemo} from 'react';
import Svg, {Circle, G, Path} from 'react-native-svg';

import {useAppTheme} from '@themes/getTheme';

import type {TravelEntries, TravelStatus} from '@store/stores/travel';

import worldMapData from './worldMap.json';

type WorldMapData = {
  width: number;
  height: number;
  /** One path per country, keyed by cca3 (generated by yarn map:generate). */
  shapes: {id: string; d: string}[];
  /** Disputed land that belongs to no country in the dataset. */
  neutral: string;
  /** Dots for countries too small to see or tap, keyed by cca3. */
  points: Record<string, [number, number]>;
};

const worldMap = worldMapData as unknown as WorldMapData;

export const MAP_ASPECT_RATIO = worldMap.width / worldMap.height;

const BORDER_WIDTH = 0.5;
const DOT_RADIUS = 2.4;
// Dots are tiny; give them a bigger, invisible touch target.
const DOT_TOUCH_RADIUS = 5;
const SELECTED_BORDER_WIDTH = 1.5;

export type WorldMapProps = {
  width: number;
  travelEntries: TravelEntries;
  selected?: string | null;
  /** Without it the map ignores touches (e.g. a preview inside a button). */
  onCountryPress?: (cca3: string) => void;
};

type CountryShapeProps = {
  id: string;
  d: string;
  fill: string;
  onPress?: (cca3: string) => void;
};

// Memoised so changing one country's status only re-renders its path.
const CountryShape = memo(({id, d, fill, onPress}: CountryShapeProps) => (
  <Path d={d} fill={fill} onPress={onPress ? () => onPress(id) : undefined} />
));

type CountryDotProps = Omit<CountryShapeProps, 'd'> & {x: number; y: number};

const CountryDot = memo(({id, x, y, fill, onPress}: CountryDotProps) => (
  <G>
    <Circle cx={x} cy={y} r={DOT_RADIUS} fill={fill} />
    {onPress && (
      <Circle
        cx={x}
        cy={y}
        r={DOT_TOUCH_RADIUS}
        fill={'#000'}
        fillOpacity={0}
        onPress={() => onPress(id)}
      />
    )}
  </G>
));

const WorldMap = ({
  width,
  travelEntries,
  selected,
  onCountryPress,
}: WorldMapProps) => {
  const {theme} = useAppTheme();
  const {colors} = theme;

  const fillFor = (cca3: string) => {
    const status: TravelStatus | undefined = travelEntries[cca3]?.status;
    if (status === 'visited') {
      return colors.visited;
    }
    if (status === 'wishlist') {
      return colors.wishlist;
    }
    return colors.mapLand;
  };

  const selectedShape = useMemo(
    () => worldMap.shapes.find(shape => shape.id === selected),
    [selected],
  );
  const selectedPoint = selected ? worldMap.points[selected] : undefined;

  return (
    <Svg
      width={width}
      height={width / MAP_ASPECT_RATIO}
      viewBox={`0 0 ${worldMap.width} ${worldMap.height}`}
      pointerEvents={onCountryPress ? 'auto' : 'none'}>
      <G
        stroke={colors.surface}
        strokeWidth={BORDER_WIDTH}
        strokeLinejoin={'round'}>
        <Path d={worldMap.neutral} fill={colors.mapLand} />
        {worldMap.shapes.map(({id, d}) => (
          <CountryShape
            key={id}
            id={id}
            d={d}
            fill={fillFor(id)}
            onPress={onCountryPress}
          />
        ))}
        {Object.entries(worldMap.points).map(([id, [x, y]]) => (
          <CountryDot
            key={id}
            id={id}
            x={x}
            y={y}
            fill={fillFor(id)}
            onPress={onCountryPress}
          />
        ))}
      </G>
      {/* Drawn last so its outline is never hidden under a neighbour. */}
      <G
        stroke={colors.primary}
        strokeWidth={SELECTED_BORDER_WIDTH}
        strokeLinejoin={'round'}
        fill={'none'}>
        {selectedShape && <Path d={selectedShape.d} />}
        {selectedPoint && (
          <Circle
            cx={selectedPoint[0]}
            cy={selectedPoint[1]}
            r={DOT_RADIUS + 1}
          />
        )}
      </G>
    </Svg>
  );
};

export default WorldMap;
